            SELECT gen_random_uuid(), id, 'การทำให้ผู้อื่นคล้อยตามจนตัดสินใจซื้อสินค้าผ่านการบอกต่ออย่างจริงใจและเร้าอารมณ์', 'COMMUNITY_DEFINED', 'Social Media Lexical Group', TRUE
