            INSERT INTO modern_term_examples (id, modern_term_id, example_text, context_note, source_attribution, register)
            SELECT gen_random_uuid(), id, 'เพื่อนป้ายยาหูฟังไร้สายตัวใหม่มา พอลองฟังเสียงแล้วกดสั่งซื้อทันทีเลย', 'การพูดคุยทั่วไปในกลุ่มเพื่อนและสื่อสังคมออนไลน์', 'โซเชียลมีเดียทั่วไป', 'SLANG'
