            INSERT INTO modern_term_relationships (id, modern_term_id, target_term, target_modern_term_id, relationship_type, source_type, confidence, notes)
            SELECT gen_random_uuid(), id, 'โน้มน้าว', (SELECT id FROM modern_terms WHERE term = 'โน้มน้าว' LIMIT 1), 'FORMAL_ALTERNATIVE', 'AI_INFERRED', 0.94, 'คำที่เป็นทางการ เหมาะสำหรับใช้ในงานเขียนวิชาการหรือบริบทที่เป็นทางการ'
