            'คำยืมจากภาษาอังกฤษ (Influencer) หมายถึง ผู้มีอิทธิพลทางความคิดหรือพฤติกรรมบนโลกออนไลน์ ซึ่งมีผู้ติดตามจำนวนมากและสามารถโน้มน้าวการตัดสินใจของผู้รับสารได้',
            '2016-01-01',
            '2026-03-01',
            0.95,
            1,
            'in-flu-en-soe',
            'Influencer: A person with the ability to influence potential buyers or followers by promoting or recommending items on social media.',
            'อิน-ฟลู-เอ็น-เซ่อ',
            'ในรายงานทางวิชาการและการตลาดอย่างเป็นทางการ ควรใช้คำว่า ''ผู้มีอิทธิพลทางสื่อสังคมออนไลน์'' หรือ ''ผู้มีอิทธิพลทางความคิด''',
            (SELECT id FROM words WHERE headword = 'อินฟลูเอนเซอร์' OR headword_clean = 'อินฟลูเอนเซอร์' LIMIT 1)
        )
        ON CONFLICT (slug) DO UPDATE SET
            term = EXCLUDED.term,
            normalized_term = EXCLUDED.normalized_term,
            description = EXCLUDED.description,
            transliteration = EXCLUDED.transliteration,
            english_meaning = EXCLUDED.english_meaning,
            pronunciation = EXCLUDED.pronunciation,
            usage_warning = EXCLUDED.usage_warning,
            official_word_id = EXCLUDED.official_word_id,
            updated_at = NOW();
        

