            INSERT INTO modern_term_definitions (id, modern_term_id, definition, definition_type, generated_by, verified)
            SELECT gen_random_uuid(), id, 'ผู้ที่สร้างฐานผู้ติดตามบนเครือข่ายสังคมออนไลน์ และมีพลังในการโน้มน้าวทัศนคติ พฤติกรรม หรือการตัดสินใจซื้อของกลุ่มผู้ติดตามผ่านการแบ่งปันประสบการณ์และความคิดเห็น', 'SOURCE_DEFINED', NULL, TRUE
            FROM modern_terms WHERE slug = 'influencer'
            AND NOT EXISTS (
