            );
            

            INSERT INTO modern_term_examples (id, modern_term_id, example_text, context_note, source_attribution, register)
            SELECT gen_random_uuid(), id, 'แบรนด์เครื่องสำอางเลือกใช้อินฟลูเอนเซอร์สายรีวิวเพื่อช่วยสร้างความน่าเชื่อถือให้กับผลิตภัณฑ์เปิดตัวใหม่', 'แผนการตลาดและการประชาสัมพันธ์', 'กลยุทธ์การตลาดแบรนด์', 'SEMI_FORMAL'
            FROM modern_terms WHERE slug = 'influencer'
            AND NOT EXISTS (
