            INSERT INTO modern_term_examples (id, modern_term_id, example_text, context_note, source_attribution, register)
            SELECT gen_random_uuid(), id, 'ทางการเตือนประชาชนให้ระวังมิจฉาชีพใช้เทคโนโลยี Deepfake ปลอมเสียงและใบหน้าของคนรู้จักมาหลอกยืมเงิน', 'ข่าวเตือนภัยความมั่นคงปลอดภัยไซเบอร์', 'ข่าวเตือนภัยอาชญากรรมทางเทคโนโลยี', 'SEMI_FORMAL'
