        -- Term: ด้อม
        INSERT INTO modern_terms (
            id, term, normalized_term, slug, language, term_type, status,
            origin, register, audience, description, first_seen_at, last_seen_at,
            confidence, source_count, transliteration, english_meaning, pronunciation,
            usage_warning, official_word_id
        ) VALUES (
            gen_random_uuid(),
            'ด้อม',
            'ด้อม',
            'dom',
            'th',
            'SLANG',
            'COMMON',
            'ENGLISH_BORROWING',
            'SLANG',
            'SOCIAL_MEDIA',
            'คำสแลงตัดทอนมาจากคำว่า แฟนด้อม (Fandom) หมายถึง กลุ่มแฟนคลับหรือกลุ่มผู้ชื่นชอบศิลปิน ดารา ไอดอล การ์ตูน หรือผลงานสร้างสรรค์ร่วมกัน',
            '2018-01-01',
            '2026-03-01',
            0.94,
            1,
            'dom',
            'Fandom / Standom: A dedicated community of fans who passionately support a celebrity, music group, or pop culture franchise.',
            'ด้อม',
            'เป็นสแลงภาษาพูดในกลุ่มแฟนคลับและสื่อสังคมออนไลน์ ไม่ควรใช้ในงานวิชาการ ควรใช้คำว่า ''กลุ่มผู้สนับสนุน'' หรือ ''กลุ่มแฟนคลับ''',
            (SELECT id FROM words WHERE headword = 'ด้อม' OR headword_clean = 'ด้อม' LIMIT 1)
        )
        ON CONFLICT (slug) DO UPDATE SET
            term = EXCLUDED.term,
            normalized_term = EXCLUDED.normalized_term,
            description = EXCLUDED.description,
            transliteration = EXCLUDED.transliteration,
            english_meaning = EXCLUDED.english_meaning,
            pronunciation = EXCLUDED.pronunciation,
            usage_warning = EXCLUDED.usage_warning,
            official_word_id = EXCLUDED.official_word_id,
            updated_at = NOW();
        

