            INSERT INTO modern_term_definitions (id, modern_term_id, definition, definition_type, generated_by, verified)
            SELECT gen_random_uuid(), id, 'กลุ่มสังคมของผู้ที่มีความสนใจ ชื่นชอบ และสนับสนุนบุคคล ศิลปิน วงดนตรี หรือผลงานชิ้นเดียวกันอย่างเหนียวแน่นบนแพลตฟอร์มดิจิทัล', 'SOURCE_DEFINED', NULL, TRUE
            FROM modern_terms WHERE slug = 'dom'
