            );
            

            INSERT INTO modern_term_examples (id, modern_term_id, example_text, context_note, source_attribution, register)
            SELECT gen_random_uuid(), id, 'ชาวด้อมร่วมใจกันจัดกิจกรรมการกุศลเนื่องในโอกาสวันคล้ายวันเกิดของศิลปินคนโปรด', 'ข่าวกิจกรรมแฟนคลับศิลปิน', 'ข่าวบันเทิงออนไลน์', 'SLANG'
            FROM modern_terms WHERE slug = 'dom'
