                WHERE mte.modern_term_id = modern_terms.id AND mte.example_text = 'ชาวด้อมร่วมใจกันจัดกิจกรรมการกุศลเนื่องในโอกาสวันคล้ายวันเกิดของศิลปินคนโปรด'
