            INSERT INTO modern_term_relationships (id, modern_term_id, target_term, target_modern_term_id, relationship_type, source_type, confidence, notes)
            SELECT gen_random_uuid(), id, 'กลุ่มแฟนคลับ', (SELECT id FROM modern_terms WHERE term = 'กลุ่มแฟนคลับ' LIMIT 1), 'FORMAL_ALTERNATIVE', 'AI_INFERRED', 0.93, 'คำกึ่งทางการที่เป็นที่ยอมรับทั่วไป'
            FROM modern_terms WHERE slug = 'dom'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_relationships mtr
                WHERE mtr.modern_term_id = modern_terms.id AND mtr.target_term = 'กลุ่มแฟนคลับ' AND mtr.relationship_type = 'FORMAL_ALTERNATIVE'
            );
            

