        -- Term: ฟีล
        INSERT INTO modern_terms (
            id, term, normalized_term, slug, language, term_type, status,
            origin, register, audience, description, first_seen_at, last_seen_at,
            confidence, source_count, transliteration, english_meaning, pronunciation,
            usage_warning, official_word_id
        ) VALUES (
            gen_random_uuid(),
            'ฟีล',
            'ฟีล',
            'feel',
            'th',
            'BORROWED_WORD',
            'COMMON',
            'ENGLISH_BORROWING',
            'INFORMAL',
            'GENERAL',
            'คำยืมจากภาษาอังกฤษ (Feel / Feeling) มักใช้เป็นคำนามหรือคำกริยาช่วย หมายถึง บรรยากาศ อารมณ์ ความรู้สึก หรือฟีลลิ่งของการกระทำหรือสถานที่นั้น ๆ',
            '2016-01-01',
            '2026-03-01',
            0.94,
            1,
            'fil',
            'Feel / Vibe: Mood, sensation, atmosphere, or impression of a situation or setting.',
            'ฟีล',
            'เป็นภาษาพูดและการสื่อสารส่วนบุคคล ในงานวิชาการหรือหนังสือราชการควรใช้ ''ความรู้สึก'' ''บรรยากาศ'' หรือ ''อารมณ์''',
            (SELECT id FROM words WHERE headword = 'ฟีล' OR headword_clean = 'ฟีล' LIMIT 1)
        )
        ON CONFLICT (slug) DO UPDATE SET
            term = EXCLUDED.term,
            normalized_term = EXCLUDED.normalized_term,
            description = EXCLUDED.description,
            transliteration = EXCLUDED.transliteration,
            english_meaning = EXCLUDED.english_meaning,
            pronunciation = EXCLUDED.pronunciation,
            usage_warning = EXCLUDED.usage_warning,
            official_word_id = EXCLUDED.official_word_id,
            updated_at = NOW();
        

            INSERT INTO modern_term_categories (id, modern_term_id, category)
