            INSERT INTO modern_term_sources (id, modern_term_id, source_type, source_name, source_url, source_date, excerpt, license, verification_status)
            SELECT gen_random_uuid(), id, 'PUBLIC_DATASET', 'คลังคำภาษาพูดในสื่อสังคมไทยร่วมสมัย', 'https://corpus.example/spoken/feel', '2019-10-04', 'ฟีล: การยืมคำว่า feel มาแสดงอารมณ์และบรรยากาศ', 'CC-BY-4.0', 'VERIFIED'
            FROM modern_terms WHERE slug = 'feel'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_sources mts
                WHERE mts.modern_term_id = modern_terms.id AND mts.source_name = 'คลังคำภาษาพูดในสื่อสังคมไทยร่วมสมัย'
            );
            

            INSERT INTO modern_term_definitions (id, modern_term_id, definition, definition_type, generated_by, verified)
            SELECT gen_random_uuid(), id, 'อารมณ์ ความรู้สึกร่วม หรือบรรยากาศแวดล้อมที่เกิดขึ้นในขณะใดขณะหนึ่ง หรือความรู้สึกที่ได้รับจากสิ่งใดสิ่งหนึ่ง', 'SOURCE_DEFINED', NULL, TRUE
            FROM modern_terms WHERE slug = 'feel'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_definitions mtd
                WHERE mtd.modern_term_id = modern_terms.id AND mtd.definition = 'อารมณ์ ความรู้สึกร่วม หรือบรรยากาศแวดล้อมที่เกิดขึ้นในขณะใดขณะหนึ่ง หรือความรู้สึกที่ได้รับจากสิ่งใดสิ่งหนึ่ง'
            );
            

            INSERT INTO modern_term_examples (id, modern_term_id, example_text, context_note, source_attribution, register)
            SELECT gen_random_uuid(), id, 'คาเฟ่ริมแม่น้ำร้านนี้ได้ฟีลเหมือนกำลังนั่งพักผ่อนอยู่ในเมืองชนบทของญี่ปุ่น', 'การรีวิวสถานที่ท่องเที่ยว', 'รีวิวท่องเที่ยวไลฟ์สไตล์', 'INFORMAL'
            FROM modern_terms WHERE slug = 'feel'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_examples mte
                WHERE mte.modern_term_id = modern_terms.id AND mte.example_text = 'คาเฟ่ริมแม่น้ำร้านนี้ได้ฟีลเหมือนกำลังนั่งพักผ่อนอยู่ในเมืองชนบทของญี่ปุ่น'
            );
            

            INSERT INTO modern_term_relationships (id, modern_term_id, target_term, target_modern_term_id, relationship_type, source_type, confidence, notes)
            SELECT gen_random_uuid(), id, 'ความรู้สึก', (SELECT id FROM modern_terms WHERE term = 'ความรู้สึก' LIMIT 1), 'FORMAL_ALTERNATIVE', 'AI_INFERRED', 0.95, 'คำทางการมาตรฐาน'
            FROM modern_terms WHERE slug = 'feel'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_relationships mtr
                WHERE mtr.modern_term_id = modern_terms.id AND mtr.target_term = 'ความรู้สึก' AND mtr.relationship_type = 'FORMAL_ALTERNATIVE'
            );
            

            INSERT INTO modern_term_relationships (id, modern_term_id, target_term, target_modern_term_id, relationship_type, source_type, confidence, notes)
            SELECT gen_random_uuid(), id, 'บรรยากาศ', (SELECT id FROM modern_terms WHERE term = 'บรรยากาศ' LIMIT 1), 'FORMAL_ALTERNATIVE', 'AI_INFERRED', 0.92, 'ใช้เมื่อหมายถึงฟีลของสถานที่หรือบริบทแวดล้อม'
            FROM modern_terms WHERE slug = 'feel'
