        -- Term: งานเข้า
        INSERT INTO modern_terms (
            id, term, normalized_term, slug, language, term_type, status,
            origin, register, audience, description, first_seen_at, last_seen_at,
            confidence, source_count, transliteration, english_meaning, pronunciation,
            usage_warning, official_word_id
        ) VALUES (
            gen_random_uuid(),
            'งานเข้า',
            'งานเข้า',
            'ngan-khao',
            'th',
            'PHRASE',
            'COMMON',
            'COMMUNITY',
            'INFORMAL',
            'GENERAL',
            'สำนวนหรือคำสแลงร่วมสมัย หมายถึง เกิดเรื่องยุ่งยาก ปัญหาไม่คาดคิด หรือมีภาระงานเร่งด่วนถาโถมเข้ามาอย่างกะทันหัน',
            '2008-01-01',
            '2026-03-01',
            0.96,
            1,
            'ngan-khao',
            'In trouble / swamped with unexpected troubles or sudden workload.',
            'งาน-เข้า',
            'เป็นภาษาพูดและสแลงสนทนา ไม่ควรใช้ในหนังสือราชการหรือรายงานผู้บริหาร ควรใช้ ''เกิดปัญหาขัดข้อง'' หรือ ''มีภาระงานเร่งด่วนเพิ่มขึ้น''',
            (SELECT id FROM words WHERE headword = 'งานเข้า' OR headword_clean = 'งานเข้า' LIMIT 1)
        )
        ON CONFLICT (slug) DO UPDATE SET
            term = EXCLUDED.term,
            normalized_term = EXCLUDED.normalized_term,
            description = EXCLUDED.description,
            transliteration = EXCLUDED.transliteration,
            english_meaning = EXCLUDED.english_meaning,
            pronunciation = EXCLUDED.pronunciation,
            usage_warning = EXCLUDED.usage_warning,
            official_word_id = EXCLUDED.official_word_id,
            updated_at = NOW();
        

