            INSERT INTO modern_term_definitions (id, modern_term_id, definition, definition_type, generated_by, verified)
            SELECT gen_random_uuid(), id, 'สถานการณ์ที่มีปัญหา ความเดือดร้อน หรือภาระความรับผิดชอบเกิดขึ้นอย่างกะทันหันโดยไม่ได้คาดหมายไว้ล่วงหน้า', 'SOURCE_DEFINED', NULL, TRUE
            FROM modern_terms WHERE slug = 'ngan-khao'
