            INSERT INTO modern_term_examples (id, modern_term_id, example_text, context_note, source_attribution, register)
            SELECT gen_random_uuid(), id, 'กำลังจะเลิกงานอยู่แล้ว เซิร์ฟเวอร์หลักเกิดล่มกะทันหัน งานเข้ากันทั้งแผนกไอที', 'การพูดคุยในที่ทำงานเมื่อเกิดเหตุฉุกเฉิน', 'บทสนทนาในที่ทำงาน', 'INFORMAL'
