            INSERT INTO modern_term_relationships (id, modern_term_id, target_term, target_modern_term_id, relationship_type, source_type, confidence, notes)
            SELECT gen_random_uuid(), id, 'เกิดปัญหาขัดข้องกะทันหัน', (SELECT id FROM modern_terms WHERE term = 'เกิดปัญหาขัดข้องกะทันหัน' LIMIT 1), 'FORMAL_ALTERNATIVE', 'AI_INFERRED', 0.92, 'คำทางการสำหรับรายงานเหตุการณ์'
