        -- Term: Viral
        INSERT INTO modern_terms (
            id, term, normalized_term, slug, language, term_type, status,
            origin, register, audience, description, first_seen_at, last_seen_at,
            confidence, source_count, transliteration, english_meaning, pronunciation,
            usage_warning, official_word_id
        ) VALUES (
            gen_random_uuid(),
            'Viral',
            'viral',
            'viral',
            'en',
            'INTERNET_TERM',
            'COMMON',
            'ENGLISH_BORROWING',
            'SEMI_FORMAL',
            'GENERAL',
            'ทับศัพท์ว่า ไวรัล หมายถึง ปรากฏการณ์ที่ข้อมูล ข่าวสาร รูปภาพ หรือวิดีโอแพร่กระจายและส่งต่ออย่างรวดเร็วและเป็นวงกว้างบนเครือข่ายอินเทอร์เน็ต คล้ายการแพร่ระบาดของไวรัส',
            '2010-01-01',
            '2026-03-01',
            0.97,
            1,
            'ไวรัล',
            'Viral: Relating to or involving an image, video, or piece of information that is circulated rapidly and widely from one internet user to another.',
            'ไว-รัล',
            'ใช้ทั่วไปในการตลาดและสื่อสารมวลชน หากใช้ในภาษาไทยทางการนิยมใช้คำว่า ''การแพร่กระจายอย่างรวดเร็วบนโลกออนไลน์''',
            (SELECT id FROM words WHERE headword = 'Viral' OR headword_clean = 'Viral' LIMIT 1)
        )
        ON CONFLICT (slug) DO UPDATE SET
            term = EXCLUDED.term,
            normalized_term = EXCLUDED.normalized_term,
            description = EXCLUDED.description,
            transliteration = EXCLUDED.transliteration,
            english_meaning = EXCLUDED.english_meaning,
            pronunciation = EXCLUDED.pronunciation,
            usage_warning = EXCLUDED.usage_warning,
            official_word_id = EXCLUDED.official_word_id,
            updated_at = NOW();
        

            INSERT INTO modern_term_categories (id, modern_term_id, category)
            SELECT gen_random_uuid(), id, 'INTERNET'
            FROM modern_terms WHERE slug = 'viral'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_categories mtc
                WHERE mtc.modern_term_id = modern_terms.id AND mtc.category = 'INTERNET'
            );
            

            INSERT INTO modern_term_categories (id, modern_term_id, category)
            SELECT gen_random_uuid(), id, 'SOCIAL_MEDIA'
            FROM modern_terms WHERE slug = 'viral'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_categories mtc
                WHERE mtc.modern_term_id = modern_terms.id AND mtc.category = 'SOCIAL_MEDIA'
            );
            

            INSERT INTO modern_term_categories (id, modern_term_id, category)
            SELECT gen_random_uuid(), id, 'BUSINESS'
            FROM modern_terms WHERE slug = 'viral'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_categories mtc
                WHERE mtc.modern_term_id = modern_terms.id AND mtc.category = 'BUSINESS'
            );
            

            INSERT INTO modern_term_sources (id, modern_term_id, source_type, source_name, source_url, source_date, excerpt, license, verification_status)
            SELECT gen_random_uuid(), id, 'PUBLIC_DATASET', 'สมาคมการตลาดดิจิทัลไทย (Digital Marketing Association)', 'https://dmat.example/terms/viral-marketing', '2018-09-12', 'ไวรัลมาร์เก็ตติง: กลยุทธ์การสื่อสารแบบปากต่อปากบนโลกออนไลน์', 'CC-BY-4.0', 'VERIFIED'
            FROM modern_terms WHERE slug = 'viral'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_sources mts
                WHERE mts.modern_term_id = modern_terms.id AND mts.source_name = 'สมาคมการตลาดดิจิทัลไทย (Digital Marketing Association)'
            );
            

            INSERT INTO modern_term_definitions (id, modern_term_id, definition, definition_type, generated_by, verified)
            SELECT gen_random_uuid(), id, 'ลักษณะของเนื้อหาที่ได้รับความนิยมสูง มีการกดแชร์และบอกต่ออย่างก้าวกระโดดบนสื่อสังคมออนไลน์ จนกลายเป็นประเด็นที่คนในสังคมพูดถึงอย่างกว้างขวางในเวลาอันรวดเร็ว', 'SOURCE_DEFINED', NULL, TRUE
            FROM modern_terms WHERE slug = 'viral'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_definitions mtd
                WHERE mtd.modern_term_id = modern_terms.id AND mtd.definition = 'ลักษณะของเนื้อหาที่ได้รับความนิยมสูง มีการกดแชร์และบอกต่ออย่างก้าวกระโดดบนสื่อสังคมออนไลน์ จนกลายเป็นประเด็นที่คนในสังคมพูดถึงอย่างกว้างขวางในเวลาอันรวดเร็ว'
            );
            

            INSERT INTO modern_term_examples (id, modern_term_id, example_text, context_note, source_attribution, register)
            SELECT gen_random_uuid(), id, 'คลิปวิดีโอทำความดีของเด็กนักเรียนกลายเป็นไวรัลที่สร้างความประทับใจให้ผู้คนทั่วประเทศ', 'ข่าวสารออนไลน์และสังคม', 'สำนักข่าวออนไลน์', 'SEMI_FORMAL'
            FROM modern_terms WHERE slug = 'viral'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_examples mte
                WHERE mte.modern_term_id = modern_terms.id AND mte.example_text = 'คลิปวิดีโอทำความดีของเด็กนักเรียนกลายเป็นไวรัลที่สร้างความประทับใจให้ผู้คนทั่วประเทศ'
            );
            

            INSERT INTO modern_term_relationships (id, modern_term_id, target_term, target_modern_term_id, relationship_type, source_type, confidence, notes)
            SELECT gen_random_uuid(), id, 'การแพร่กระจายอย่างรวดเร็วบนสื่อออนไลน์', (SELECT id FROM modern_terms WHERE term = 'การแพร่กระจายอย่างรวดเร็วบนสื่อออนไลน์' LIMIT 1), 'FORMAL_ALTERNATIVE', 'AI_INFERRED', 0.91, 'คำทางการเชิงนิเทศศาสตร์'
            FROM modern_terms WHERE slug = 'viral'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_relationships mtr
                WHERE mtr.modern_term_id = modern_terms.id AND mtr.target_term = 'การแพร่กระจายอย่างรวดเร็วบนสื่อออนไลน์' AND mtr.relationship_type = 'FORMAL_ALTERNATIVE'
            );
            

