            INSERT INTO modern_term_sources (id, modern_term_id, source_type, source_name, source_url, source_date, excerpt, license, verification_status)
            SELECT gen_random_uuid(), id, 'COMMUNITY', 'คลังคำสแลงบันเทิงไทย', 'https://thai-slang.example/terms/pang', '2017-06-20', 'ปัง: ความสำเร็จที่ดังเปรี้ยงปร้าง', 'CC-BY-4.0', 'VERIFIED'
            FROM modern_terms WHERE slug = 'pang'
