            INSERT INTO modern_term_definitions (id, modern_term_id, definition, definition_type, generated_by, verified)
            SELECT gen_random_uuid(), id, 'ประสบผลสำเร็จอย่างงดงาม โดดเด่นเป็นที่สะดุดตา หรือได้รับความนิยมอย่างถล่มทลาย', 'SOURCE_DEFINED', NULL, TRUE
            FROM modern_terms WHERE slug = 'pang'
            AND NOT EXISTS (
