                WHERE mtd.modern_term_id = modern_terms.id AND mtd.definition = 'ประสบผลสำเร็จอย่างงดงาม โดดเด่นเป็นที่สะดุดตา หรือได้รับความนิยมอย่างถล่มทลาย'
            );
            

            INSERT INTO modern_term_examples (id, modern_term_id, example_text, context_note, source_attribution, register)
            SELECT gen_random_uuid(), id, 'เพลงใหม่ของวงเปิดตัววันแรกก็ปังมาก ยอดวิวพุ่งแตะหลักล้านภายในไม่กี่ชั่วโมง', 'ข่าววงการบันเทิง', 'ข่าวบันเทิงออนไลน์', 'SLANG'
            FROM modern_terms WHERE slug = 'pang'
            AND NOT EXISTS (
