                WHERE mte.modern_term_id = modern_terms.id AND mte.example_text = 'เพลงใหม่ของวงเปิดตัววันแรกก็ปังมาก ยอดวิวพุ่งแตะหลักล้านภายในไม่กี่ชั่วโมง'
            );
            

            INSERT INTO modern_term_relationships (id, modern_term_id, target_term, target_modern_term_id, relationship_type, source_type, confidence, notes)
            SELECT gen_random_uuid(), id, 'ประสบความสำเร็จอย่างโดดเด่น', (SELECT id FROM modern_terms WHERE term = 'ประสบความสำเร็จอย่างโดดเด่น' LIMIT 1), 'FORMAL_ALTERNATIVE', 'AI_INFERRED', 0.92, 'คำทางการสำหรับความสำเร็จ'
            FROM modern_terms WHERE slug = 'pang'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_relationships mtr
                WHERE mtr.modern_term_id = modern_terms.id AND mtr.target_term = 'ประสบความสำเร็จอย่างโดดเด่น' AND mtr.relationship_type = 'FORMAL_ALTERNATIVE'
            );
            

            INSERT INTO modern_term_relationships (id, modern_term_id, target_term, target_modern_term_id, relationship_type, source_type, confidence, notes)
