            SELECT gen_random_uuid(), id, 'AI', (SELECT id FROM modern_terms WHERE term = 'AI' LIMIT 1), 'RELATED', 'AI_INFERRED', 0.99, 'ChatGPT เป็นแอปพลิเคชันปัญญาประดิษฐ์'
            FROM modern_terms WHERE slug = 'chatgpt'
            AND NOT EXISTS (
                SELECT 1 FROM modern_term_relationships mtr
                WHERE mtr.modern_term_id = modern_terms.id AND mtr.target_term = 'AI' AND mtr.relationship_type = 'RELATED'
            );
            

            INSERT INTO modern_term_relationships (id, modern_term_id, target_term, target_modern_term_id, relationship_type, source_type, confidence, notes)
